using sv_cc722bab6acc4132a8e84748b6f1bde1.Services;

namespace sv_cc722bab6acc4132a8e84748b6f1bde1.Components.Pages;

public partial class Settings
{
    private string activeSection = "Profile";
    private bool isLoading;
    private string? toastMessage;
    private string toastType = "";

    // Profile state
    private UserProfile? savedProfile;
    private UserProfile? editProfile;
    private string profileDisplayName = "";
    private string profileEmail = "";
    private string profileBio = "";

    // Notifications state
    private NotificationPrefs? savedNotifPrefs;
    private bool notifEmailEnabled;
    private bool notifPushEnabled;
    private bool notifWeeklyDigest;
    private HashSet<string> mutedChannels = new();
    private List<string> availableChannels = new() { "general", "announcements", "random", "engineering", "design", "marketing" };

    // Security state
    private SecuritySettings? securitySettings;
    private bool passwordPanelExpanded;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string? passwordError;
    private bool twoFactorEnabled;
    private bool showRevokeConfirmation;
    private ActiveSession? sessionToRevoke;

    // Appearance state
    private AppearanceSettings? savedAppearance;
    private string appearanceTheme = "Light";
    private string appearanceFontSize = "Medium";
    private string appearanceLanguage = "en";
    private bool appearanceCompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadSection(activeSection);
    }

    private async Task SetSection(string section)
    {
        activeSection = section;
        await LoadSection(section);
    }

    private async Task LoadSection(string section)
    {
        isLoading = true;
        StateHasChanged();

        try
        {
            switch (section)
            {
                case "Profile":
                    savedProfile = await SettingsService.GetProfileAsync();
                    ApplyProfileToEdit(savedProfile);
                    break;
                case "Notifications":
                    savedNotifPrefs = await SettingsService.GetNotificationPrefsAsync();
                    ApplyNotifPrefsToEdit(savedNotifPrefs);
                    break;
                case "Security":
                    securitySettings = await SettingsService.GetSecuritySettingsAsync();
                    twoFactorEnabled = securitySettings.TwoFactorEnabled;
                    break;
                case "Appearance":
                    savedAppearance = await SettingsService.GetAppearanceAsync();
                    ApplyAppearanceToEdit(savedAppearance);
                    break;
            }
        }
        finally
        {
            isLoading = false;
            StateHasChanged();
        }
    }

    private void ApplyProfileToEdit(UserProfile profile)
    {
        editProfile = profile;
        profileDisplayName = profile.DisplayName;
        profileEmail = profile.Email;
        profileBio = profile.Bio;
    }

    private void ApplyNotifPrefsToEdit(NotificationPrefs prefs)
    {
        notifEmailEnabled = prefs.EmailNotifications;
        notifPushEnabled = prefs.PushNotifications;
        notifWeeklyDigest = prefs.WeeklyDigest;
        mutedChannels = new HashSet<string>(prefs.MutedChannels);
    }

    private void ApplyAppearanceToEdit(AppearanceSettings settings)
    {
        appearanceTheme = settings.Theme;
        appearanceFontSize = settings.FontSize;
        appearanceLanguage = settings.Language;
        appearanceCompactMode = settings.CompactMode;
    }

    // Profile actions
    private async Task SaveProfile()
    {
        var updated = new UserProfile(profileDisplayName, profileEmail, editProfile?.AvatarUrl ?? "", profileBio);
        await SettingsService.SaveProfileAsync(updated);
        savedProfile = updated;
        editProfile = updated;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (savedProfile != null)
        {
            ApplyProfileToEdit(savedProfile);
        }
    }

    // Notifications actions
    private void ToggleMutedChannel(string channel, bool isMuted)
    {
        if (isMuted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(notifEmailEnabled, notifPushEnabled, notifWeeklyDigest, mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        savedNotifPrefs = prefs;
        ShowToast("Notification preferences saved!", "success");
    }

    // Security actions
    private async Task UpdatePassword()
    {
        passwordError = null;

        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            passwordError = "All password fields are required.";
            return;
        }

        if (newPassword != confirmPassword)
        {
            passwordError = "New password and confirmation do not match.";
            return;
        }

        try
        {
            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
            passwordPanelExpanded = false;
            ShowToast("Password updated successfully!", "success");
        }
        catch (Exception ex)
        {
            passwordError = ex.Message;
        }
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        sessionToRevoke = session;
        showRevokeConfirmation = true;
    }

    private async Task RevokeSession()
    {
        if (sessionToRevoke != null)
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
            securitySettings = await SettingsService.GetSecuritySettingsAsync();
            showRevokeConfirmation = false;
            sessionToRevoke = null;
            ShowToast("Session revoked.", "success");
        }
    }

    // Appearance actions
    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{appearanceTheme.ToLowerInvariant()} preview-font-{appearanceFontSize.ToLowerInvariant()}";
        if (appearanceCompactMode)
            classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(appearanceTheme, appearanceFontSize, appearanceLanguage, appearanceCompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        savedAppearance = settings;
        ShowToast("Appearance settings saved!", "success");
    }

    // Toast
    private void ShowToast(string message, string type)
    {
        toastMessage = message;
        toastType = type;
        StateHasChanged();
        _ = DismissToastAfterDelay();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(3000);
        toastMessage = null;
        await InvokeAsync(StateHasChanged);
    }
}

.settings-container {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* Sidebar Navigation */
.settings-sidebar {
    width: 240px;
